namespace AlphaPlus.Settings.Site.Features.Shared.Helpers
{
    using System;
    using System.Collections;
    using System.Globalization;
    using System.Linq;
    using System.Net;
    using System.Resources;
    using System.Text;
    using System.Threading;

    public static class ResourcesJsonConverter 
    {
        public static string ToConvert(string language, ResourceManager resourceManager)
        {
            Thread.CurrentThread.CurrentCulture = new CultureInfo(language);
            Thread.CurrentThread.CurrentUICulture = Thread.CurrentThread.CurrentCulture;
            ResourceSet resourceSet = resourceManager.GetResourceSet(CultureInfo.CurrentUICulture, true, true);

            var resourceJson = string.Join(",",
                resourceSet.Cast<DictionaryEntry>()
                .Select(x => $"\"{x.Key.ToString()}\":\"{WebUtility.HtmlEncode(x.Value.ToString())}\""));

            return string.Format("{0}{1}{2}", "{", resourceJson, "}");
        }
    }
}